private boolean unlink(ListNodeImpl<E> node) {
    // Update pointers of adjacent nodes
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        head = node.next;
    }

    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        tail = node.prev;
    }

    // Detach the node completely
    node.prev = null;
    node.next = null;

    // Adjust the list metadata
    if (size > 0) {
        size--;
        return true;
    }
    return false;
}

